<template>
  <div class="report-view">
    <NavBarVue />
    <b-container fluid class="bv-example-row">
      <div class="container-group">
        <div class="card">
          <div class="card-body">
            <!-- Reports -->
            <b-overlay :show="isLoading" rounded="sm">
              <b-row>
                <b-col>
                  <b-row class="mb-1">
                    <b-col>
                      <b-form-datepicker
                        placeholder="M"
                        block
                        size="sm"
                        id="from-datepicker"
                        v-model="fromDate"
                      ></b-form-datepicker
                    ></b-col>
                    <b-col cols="1" class="text-right">
                      <b-badge
                        @click="refreshData()"
                        variant="secondary"
                        pill
                        style="cursor: pointer; font-size: 10pt"
                        ><b-icon icon="search" aria-hidden="true"></b-icon>
                        Buscar
                      </b-badge></b-col
                    >
                    <b-col cols="4" class="text-right">
                      <b-badge
                        @click="generateExcelReport()"
                        variant="secondary"
                        pill
                        style="cursor: pointer; font-size: 10pt"
                        ><b-icon
                          icon="file-excel-fill"
                          aria-hidden="true"
                        ></b-icon>
                        Exportar para Google Sheets
                      </b-badge></b-col
                    >
                    <b-col cols="1" class="text-right">
                      <b-badge
                        @click="generatePDFReport()"
                        variant="secondary"
                        pill
                        style="cursor: pointer; font-size: 10pt"
                        ><b-icon
                          icon="printer-fill"
                          aria-hidden="true"
                        ></b-icon>
                        PDF
                      </b-badge></b-col
                    >
                  </b-row>

                  <table
                    class="table table-sm table-hover table-stripped text-secondary"
                    v-if="disbursedLoan.length > 0"
                  >
                    <thead>
                      <tr style="font-size: 11pt" class="text-center">
                        <th colspan="10">
                          PERÍODO DO REPORTE:
                          {{ fromDate.slice(0, 7) }}
                        </th>
                      </tr>
                    </thead>
                    <thead>
                      <tr
                        class="bg-secondary text-white"
                        style="font-size: 10pt"
                      >
                        <th>Nome do mutuário</th>
                        <th class="text-right">Capital</th>
                        <th class="text-right">Juros</th>
                        <th class="text-right">Total</th>
                        <th class="text-right">Percentagem</th>
                        <th class="text-right">Data início</th>
                        <th class="text-right">Data fim</th>
                        <th class="text-right">Dia em atrazo</th>
                        <th class="text-right">Juros de mora</th>
                        <th class="text-right">Total pago</th>
                        <th class="text-right">Valor em dívida</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="desembolsado in disbursedLoan"
                        :key="desembolsado.id"
                        style="font-size: 10pt"
                      >
                        <td>
                          {{
                            getCustomerDetails(
                              desembolsado.accountNumber
                            ).customerName.toUpperCase()
                          }}
                        </td>
                        <td
                          class="text-right"
                          v-money-format="desembolsado.amount"
                        ></td>
                        <td
                          class="text-right"
                          v-money-format="
                            desembolsado.amount * desembolsado.interestRate
                          "
                        ></td>
                        <td
                          class="text-right"
                          v-money-format="
                            desembolsado.amount +
                            desembolsado.amount * desembolsado.interestRate
                          "
                        ></td>
                        <td class="text-right">
                          {{ getRate(desembolsado.interestRate) }}
                        </td>
                        <td
                          class="text-right"
                          v-date-format="desembolsado.dateCreated"
                        ></td>
                        <td
                          class="text-right"
                          v-date-format="getDueDate(desembolsado)"
                        ></td>
                        <td class="text-right">{{ lateDays(desembolsado) }}</td>
                        <td class="text-right">
                          {{ convertMoney(latePaymentInterest(desembolsado)) }}
                        </td>
                        <td class="text-right">
                          {{
                            convertMoney(populatePaymentReceived(desembolsado))
                          }}
                        </td>
                        <td class="text-right">
                          {{
                            convertMoney(
                              getRemainingBalance(desembolsado) +
                                latePaymentInterest(desembolsado)
                            )
                          }}
                        </td>
                      </tr>
                    </tbody>
                    <!-- <tbody>
                      <tr>
                        <td><br /><br /><br /></td>
                      </tr>
                      <tr style="font-size: 16">
                        <th colspan="6">TOTAL DESEBOLSADO</th>
                        <th
                          colspan="3"
                          class="text-right"
                          v-money-format="getTotal()"
                        ></th>
                      </tr>
                      <tr style="font-size: 16">
                        <th colspan="6">TOTAL DE JUROS</th>
                        <th
                          colspan="3"
                          class="text-right"
                          v-money-format="getRateAmount()"
                        ></th>
                      </tr>
                      <tr style="font-size: 16">
                        <th colspan="6">TOTAL PAGO</th>
                        <th colspan="3" class="text-right">0</th>
                      </tr>
                      <tr style="font-size: 16">
                        <th colspan="6">TOTAL EM DÍVIDA</th>
                        <th colspan="3" class="text-right">0</th>
                      </tr>
                    </tbody> -->
                  </table>
                  <b-alert
                    class="text-center mt-3"
                    v-if="disbursedLoan.length === 0"
                    variant="danger"
                    show
                    dismissible
                    ><b-icon
                      icon="exclamation-circle-fill"
                      variant="danger"
                    ></b-icon>
                    Sem nenhuma transação registada até o momento.
                    <b>&rArr;</b>
                  </b-alert>
                </b-col>
              </b-row>
            </b-overlay>
          </div>
        </div>
      </div>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";

import NavBarVue from "@/components/NavBar";
import moment from "moment";
import axios from "axios";
import MoneyFormat from "@/utils/moneyFormat";
import DateFormat from "@/utils/dateFormat";
// import exportFromJSON from "export-from-json";
import bmLogo from "@/utils/getBMLogo";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  data: () => ({
    fromDate: moment().format("YYYY-MM-DD"),
    toDate: "",

    selectedPaymentMethod: 0,

    options: [
      { value: 0, text: "Meio de pagamento" },
      { value: 1, text: "Boca de Caixa" },
      { value: 2, text: "Depósito Bancário" },
      { value: 3, text: "Transferência Bancária" },
      { value: 4, text: "POS" },
      { value: 5, text: "Cheque" },
      { value: 6, text: "SISTAFE" },
      { value: 7, text: "M-Pesa Open-Api" },
      { value: 8, text: "E-Mola" },
    ],

    totalRecebido: 0,
    tranzactions: [],
    disbursedLoan: [],
  }),

  components: {
    NavBarVue,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "customers",
      "company",
      "updatedPassword",
      "companyLoans",
      "monthllyTransactions",
    ]),
  },

  watch: {
    fromDate: function () {
      this.getLoans();
      this.getTranzactions();
    },
  },

  created() {
    this.getLoans();
    this.getTranzactions();
  },

  methods: {
    populatePaymentReceived(loan) {
      const transactions = this.tranzactions.filter((tranz) => {
        return tranz.loanId == loan.id;
      });
      return transactions.reduce((sum, p) => sum + p.amount, 0);
    },

    convertMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    getRemainingBalance(loan) {
      const totalAmountDue = loan.amount + loan.amount * loan.interestRate;
      return totalAmountDue - this.populatePaymentReceived(loan);
    },

    lateDays(loan) {
      const diffDays = moment().diff(this.getDueDate(loan), "days");
      return diffDays >= 0 ? diffDays : 0;
    },

    latePaymentInterest(loan) {
      const diffDays = moment().diff(this.getDueDate(loan), "days");
      const latePaymentValue =
        diffDays >= 0
          ? this.getRemainingBalance(loan) * (this.company.forfeit / 100)
          : 0;

      return latePaymentValue * diffDays;
    },

    getDueDate(loan) {
      return moment(loan.dateCreated).add(1, "M");
    },

    getPaymentMethod(method) {
      if (method == 1) {
        return "Boca do Caixa";
      } else if (method == 2) {
        return "Depósito Bancário";
      } else if (method == 3) {
        return "Transferência Bancária";
      } else if (method == 4) {
        return "POS";
      } else if (method == 5) {
        return "Cheque";
      } else if (method == 6) {
        return "SISTAFE";
      } else if (method == 7) {
        return "M-Pesa Open-Api";
      } else if (method == 8) {
        return "E-Mola";
      }
    },

    getRate(rate) {
      return rate * 100 + "%";
    },

    refreshData() {
      this.getLoans();
      this.getTranzactions();
    },

    getTranzactions() {
      this.$store.commit("LOADING_STATUS", true);
      const queryString = `?from=${this.fromDate.slice(0, 7)}&companyId=${
        this.company.id
      }`;
      axios
        .get(`/api/tranzaction/${queryString}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.tranzactions = data.result;
          } else {
            this.showToast("Opps!", "warning", "Reembolsos indisponíveis.");
            this.tranzactions = [];
          }
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.tranzactions = [];
        });
    },

    getLoans() {
      // const selectedMonth = this.fromDate.slice(0, 7);
      this.disbursedLoan = this.companyLoans.filter((credit) => {
        return (
          credit.dateCreated.slice(0, 7) == this.fromDate.slice(0, 7) &&
          credit.status == 1
        );
      });
    },

    getLoanData() {
      for (let loan = 0; loan < this.disbursedLoan.length; loan++) {
        const element = this.disbursedLoan[loan];
        console.log(element.amount);
      }
    },

    getTotal() {
      return this.disbursedLoan.reduce((sum, p) => sum + p.amount, 0);
    },

    getRateAmount() {
      return this.disbursedLoan.reduce(
        (sum, p) => sum + p.amount * p.interestRate,
        0
      );
    },

    generateExcelReport() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(`/api/getRows`)
        .then((res) => {
          console.log(res.data);
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    async generatePDFReport() {
      const body = [];

      for (let row of this.disbursedLoan) {
        const rows = [];
        rows.push({
          text: this.getCustomerDetails(row.accountNumber).customerName,
          fontSize: 8,
        });
        rows.push({
          text: DateFormat.formatDate(row.dateCreated),
          fontSize: 8,
        });
        rows.push({ text: MoneyFormat.formatMoney(row.amount), fontSize: 8 });
        rows.push({ text: "Comércio", fontSize: 8 });
        rows.push({
          text: MoneyFormat.formatMoney(
            row.amount + row.amount * row.interestRate
          ),
          fontSize: 8,
        });
        rows.push({ text: "Mensal", fontSize: 8 });
        rows.push({
          text: DateFormat.formatDate(this.getDueDate(row)),
          fontSize: 8,
        });
        rows.push({ text: row.interestRate * 100 + "%", fontSize: 8 });
        rows.push({
          text: MoneyFormat.formatMoney(
            this.getRemainingBalance(row) + this.latePaymentInterest(row)
          ),
          fontSize: 8,
        });
        rows.push({ text: "", fontSize: 8 });
        rows.push({ text: this.lateDays(row), fontSize: 8 });
        rows.push({ text: "", fontSize: 8 });
        body.push(rows);
      }

      let docDefinition = {
        pageOrientation: "landscape",
        content: [
          {
            columns: [
              {
                image: bmLogo.getBMLogo(),
                width: 80,
              },
              {
                text: `BANCO DE MOÇAMBIQUE
                DEPARTAMENTO DE SUPERVISÃO PRUDENCIAL
                REPORTE PERIÓDICO DE INFORMAÇÕES DE MICROFINANÇAS
                INSTITUIÇÕES SUJEITAS À MONITORIZAÇÃO
                `,
                fontSize: 10,
                alignment: "center",
                bold: true,
              },
            ],
          },
          {
            columns: [
              [
                {
                  text: `\n\nPERÍODO DE REPORTE: ${this.fromDate.slice(0, 7)}`,
                  fontSize: 10,
                  alignment: "left",
                  bold: true,
                },
              ],
            ],
          },
          {
            text: "\n",
          },
          {
            text: `1. IDENTIFICAÇÃO DA INSTITUIÇÃO \n
            Denominação: ${this.company.companyName}
            Endereço: ${this.company.companyAddress}
            Província: Maputo Cidade
            Telefone: ${this.company.companyPhone}
            Fax: ___________________________, E-mail: ${this.company.companyEmail}
            Nº de trabalhadores: 3 (Três)
            Data de Início de Actividades: 08/08/2023
            Nome do Responsável pela Gestão da Instituição: ${this.company.companyManager}
            Instituição(ões) Representada(s): N/A
            `,
            bold: true,
            fontSize: 9,
            alignment: "left",
          },
          {
            text: "\n",
          },
          {
            table: {
              widths: [
                "*",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
                "auto",
              ],
              body: [
                [
                  { text: "Cliente (2)", style: "columnsTitle" },
                  { text: "Data (3)", style: "columnsTitle" },
                  { text: "Montante (4)", style: "columnsTitle" },
                  { text: "Finalidade (5)", style: "columnsTitle" },
                  { text: "Prestação (6)", style: "columnsTitle" },
                  {
                    text: "Periodicidade (7)",
                    style: "columnsTitle",
                  },
                  { text: "Prazo (8)", style: "columnsTitle" },
                  { text: "Juros (9)", style: "columnsTitle" },
                  { text: "Dívida (10)", style: "columnsTitle" },
                  { text: "Crédito Atraso (11)", style: "columnsTitle" },
                  { text: "Dias em Atraso (12)", style: "columnsTitle" },
                  { text: "PPEs (13)", style: "columnsTitle" },
                ],
                ...body,
                [{}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}],
              ],
            },
            layout: "lightHorizontalLines",
          },
        ],
        styles: {
          columnsTitle: {
            fontSize: 8,
            bold: true,
            color: "#000000",
          },
        },
      };

      // pdfMake.createPdf(docDefinition).download(`proforma${this.currentQuotation.name}.pdf`);
      pdfMake.createPdf(docDefinition).open();
    },

    getCustomerDetails(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      return filteredCustomer[0];
    },

    calculateTotalCollected() {
      return MoneyFormat.calculateSumOfArray(this.tranzactions);
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>
<style lang="scss" scoped>
.container-group {
  overflow: hidden auto;
  margin-left: -15px;
  width: calc(100% + 30px);
  height: calc(100vh - 55px);

  .container {
    font-size: 10pt;
    padding-top: 0px;
    padding-bottom: 15px;
  }
}

.table {
  font-size: 8pt;
  text-align: left;

  tr {
    cursor: pointer;
  }
}
</style>
